// Spawns a class 0x4F particle at a position with a direction, optionally relative to a parent.
unsigned char *spawn_trail_particle(char *parent, void *pos, float *vec) {
    int r = random_integer_below(5);
    unsigned char a = scale_ticks(r + 2);
    unsigned char b = random_integer_below(0xFF);
    unsigned char *p = create_part(0x4F);
    if (p != 0) {
        char *d = (char *)p + 0x20;
        qcopy(p + 0x10, pos);
        *(float *)(d + 0x10) = vec[0];
        *(float *)(d + 0x14) = vec[1];
        *(float *)(d + 0x18) = vec[2];
        if (parent != 0) {
            FastVecSub(d, p + 0x10, parent + 0x10);
            *(short *)(p + 0xA) = a;
        } else {
            *(short *)(p + 0xA) = a << 2;
        }
        *(char **)(d + 0x1C) = parent;
        *(int *)(p + 4) = 0x604040FF;
        p[9] = truncate_float_to_s32_r(1.0f) + 0x20;
        p[3] = 0x48;
        *(float *)(p + 0xC) = 42000.0f;
        p[8] = b;
        p[1] = 0;
        p[2] = *fleet_trail_texture_ptr;
    }
    return p;
}
extern float IntToFloat(int);
extern int FastTweenColor(int, int, float);

// Spawns a class 0x50 fading particle at a position, with colours depending on a mode and a fade step.
unsigned char *create_drone_flight_trail_record(char *pos, int mode, int step) {
    unsigned char *p;
    int n;
    if (mode)
        n = 5 - step;
    else
        n = 0xF - step;
    if (n >= 0) {
        p = create_part(0x50);
        if (p != 0) {
            qcopy(p + 0x10, pos);
            p[9] = truncate_float_to_s32_r(1.0f) + 0x70;
            *(int *)(p + 0x20) = mode;
            if (mode == 0) {
                int d = 0xF - step;
                *(int *)(p + 4) = 0x60FF3020;
                p[3] = 0x48;
                *(float *)(p + 0xC) = 630000.0f;
                *(short *)(p + 0xA) = d;
                if (step != 0) {
                    float a = IntToFloat((short)d - 1);
                    *(int *)(p + 4) = FastTweenColor(0x603F1008, *(int *)(p + 4), a / IntToFloat(*(short *)(p + 0xA)));
                }
            } else {
                int d = 5 - step;
                *(int *)(p + 4) = 0x80D0A080;
                p[3] = 0x44;
                *(float *)(p + 0xC) = 420000.0f;
                *(short *)(p + 0xA) = d;
                if (step != 0) {
                    float a = IntToFloat((short)d - 1);
                    *(int *)(p + 4) = FastTweenColor(0x30FFFFFF, *(int *)(p + 4), a / IntToFloat(*(short *)(p + 0xA)));
                }
            }
            p[1] = 0;
            p[8] = random_integer_below(0xFF);
            p[2] = *fleet_trail_texture_ptr;
        }
        return p;
    }
    return 0;
}
